INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (10, 72021, 0, 1, 0, 72, 0, 1, 1, "だからわたし、\n勇気を出して言ってみたんです！\nお友だちになりませんか、って。", 11);
